// Round 15: the same constant call as the condition of an `if` in a clocked block. Refused.
`default_nettype none
module inlff (
    input  wire [7:0] ui_in, output wire [7:0] uo_out, input  wire [7:0] uio_in,
    output wire [7:0] uio_out, output wire [7:0] uio_oe, input  wire ena,
    input  wire clk, input  wire rst_n);
/* verilator lint_off UNUSEDSIGNAL */
  function automatic integer pick(input [3:0] v, input integer k);
    if (!v[k]) pick = 0; else pick = 1;
  endfunction
/* verilator lint_on UNUSEDSIGNAL */
  reg [7:0] q;
  always @(posedge clk) begin
    if (!rst_n) q <= 8'd0;
    else if (pick(4'b1010, 6) == 1) q <= ui_in;
    else q <= ~ui_in;
  end
  assign uo_out = q;
  assign uio_out = 8'd0; assign uio_oe = 8'd0;
  wire _unused = &{1'b0, uio_in, ui_in, ena, clk, rst_n};
endmodule
